package org.eclipse.rdf4j.query.algebra.evaluation.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.Difference;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.Lateral;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.MultiProjection;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Union;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class BindingScopeAnalysisTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void parentlessNodeHasNoSubstitutedNames() {
		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(pattern("s", "o"))).isEmpty();
	}

	@Test
	void rightArgOfLateralSeesTheLateralInputNames() {
		StatementPattern right = pattern("s", "label");
		new Lateral(pattern("s", "o"), right, Set.of("s", "o"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(right)).containsExactlyInAnyOrder("s", "o");
	}

	@Test
	void leftArgOfLateralSeesNothing() {
		StatementPattern left = pattern("s", "o");
		new Lateral(left, pattern("s", "label"), Set.of("s", "o"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(left)).isEmpty();
	}

	@Test
	void nestedOperatorInsideLateralRightArgSeesTheNames() {
		StatementPattern minusRight = pattern("y", "z");
		Difference difference = new Difference(pattern("s", "y"), minusRight);
		LeftJoin optional = new LeftJoin(new SingletonSet(), difference);
		new Lateral(pattern("s", "z"), optional, Set.of("s", "z"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(minusRight)).containsExactlyInAnyOrder("s", "z");
		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(optional)).containsExactlyInAnyOrder("s", "z");
	}

	@Test
	void subSelectHidesNamesItDoesNotProjectAsSourceNames() {
		StatementPattern inner = pattern("s", "label");
		Projection projection = new Projection(inner, new ProjectionElemList(new ProjectionElem("label")), true);
		new Lateral(pattern("s", "o"), projection, Set.of("s", "o"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(inner)).isEmpty();
		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(projection)).containsExactlyInAnyOrder("s", "o");
	}

	@Test
	void subSelectKeepsNamesItProjectsAsSourceNames() {
		StatementPattern inner = pattern("s", "label");
		Projection projection = new Projection(inner,
				new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("label")), true);
		new Lateral(pattern("s", "o"), projection, Set.of("s", "o"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(inner)).containsExactly("s");
	}

	@Test
	void multiProjectionKeepsTheUnionOfSourceNames() {
		StatementPattern inner = pattern("s", "o");
		MultiProjection multiProjection = new MultiProjection(inner, List.of(
				new ProjectionElemList(new ProjectionElem("s")),
				new ProjectionElemList(new ProjectionElem("o"))));
		new Lateral(pattern("s", "x"), multiProjection, Set.of("s", "o", "x"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(inner)).containsExactlyInAnyOrder("s", "o");
	}

	@Test
	void nestedLateralsAccumulateAcrossScopes() {
		StatementPattern innermost = pattern("t", "u");
		Lateral inner = new Lateral(pattern("s", "t"), innermost, Set.of("s", "t"));
		new Lateral(pattern("s", "o"), inner, Set.of("s", "o"));

		assertThat(BindingScopeAnalysis.lateralSubstitutedNames(innermost)).containsExactlyInAnyOrder("s", "t", "o");
	}

	@Test
	void outOfScopePredicateMatchesJoinStepRules() {
		assertThat(BindingScopeAnalysis.isOutOfScopeForCorrelation(pattern("s", "o"))).isFalse();
		assertThat(BindingScopeAnalysis.isOutOfScopeForCorrelation(
				new Projection(pattern("s", "o"), new ProjectionElemList(new ProjectionElem("s")), true))).isTrue();
		assertThat(BindingScopeAnalysis.isOutOfScopeForCorrelation(
				new Filter(new Difference(pattern("s", "o"), pattern("s", "x")),
						new ValueConstant(VF.createLiteral(true)))))
								.isTrue();
		Join scoped = new Join(pattern("s", "o"), pattern("s", "x"));
		scoped.setVariableScopeChange(true);
		assertThat(BindingScopeAnalysis.isOutOfScopeForCorrelation(scoped)).isTrue();
	}

	@Test
	void differenceBehindServiceOrLateralIsNotInCurrentScope() {
		Difference difference = new Difference(pattern("s", "o"), pattern("s", "x"));
		Service service = new Service(new Var("_const_svc", VF.createIRI("urn:svc")), difference, "", Map.of(), null,
				false);
		assertThat(BindingScopeAnalysis.containsDifferenceInCurrentScope(service)).isFalse();
		Lateral lateral = new Lateral(pattern("s", "o"),
				new Difference(pattern("s", "y"), pattern("y", "z")), Set.of("s"));
		assertThat(BindingScopeAnalysis.containsDifferenceInCurrentScope(lateral)).isFalse();
		assertThat(BindingScopeAnalysis.containsDifferenceInCurrentScope(
				new Join(pattern("a", "b"), new Difference(pattern("s", "y"), pattern("y", "z"))))).isTrue();
	}

	@Test
	void correlatedInputPositionsAreTheRightArgsOfCorrelatingOperators() {
		Difference topLevel = new Difference(pattern("s", "o"), pattern("s", "x"));
		new Projection(topLevel, new ProjectionElemList(new ProjectionElem("s")));
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(topLevel)).isFalse();
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(pattern("a", "b"))).isFalse();

		Difference inOptional = new Difference(pattern("s", "y"), pattern("y", "z"));
		new LeftJoin(pattern("s", "z"), inOptional);
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inOptional)).isTrue();

		Difference inJoinRight = new Difference(pattern("s", "y"), pattern("y", "z"));
		new Join(pattern("s", "z"), new Filter(inJoinRight, new ValueConstant(VF.createLiteral(true))));
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inJoinRight)).isTrue();

		Difference inJoinLeft = new Difference(pattern("s", "y"), pattern("y", "z"));
		new Join(inJoinLeft, pattern("s", "z"));
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inJoinLeft)).isFalse();

		Difference inLateral = new Difference(pattern("s", "y"), pattern("y", "z"));
		new Lateral(pattern("s", "z"), inLateral, Set.of("s", "z"));
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inLateral)).isTrue();

		Difference inMinusRight = new Difference(pattern("s", "y"), pattern("y", "z"));
		new Difference(pattern("s", "z"), inMinusRight);
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inMinusRight)).isTrue();

		Difference inUnion = new Difference(pattern("s", "y"), pattern("y", "z"));
		new Union(pattern("s", "z"), inUnion);
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inUnion)).isFalse();
	}

	@Test
	void existsBodySubstitutesTheProbeRowAndIsNotACorrelatedPosition() {
		Difference inExists = new Difference(pattern("s", "y"), pattern("y", "z"));
		Exists exists = new Exists(inExists);
		new Filter(new Join(pattern("a", "b"), pattern("s", "z")), exists);
		assertThat(BindingScopeAnalysis.receivesCorrelatedInput(inExists)).isFalse();
	}

	@Test
	void retainKeepsOnlyRequestedNamesAndReusesCompleteInputs() {
		QueryBindingSet bindings = new QueryBindingSet(2);
		bindings.addBinding("s", VF.createIRI("urn:s"));
		bindings.addBinding("z", VF.createIRI("urn:z"));

		BindingSet restricted = BindingScopeAnalysis.retain(bindings, Set.of("z", "y"));
		assertThat(restricted.getBindingNames()).containsExactly("z");

		assertThat(BindingScopeAnalysis.retain(bindings, Set.of("s", "z"))).isSameAs(bindings);
		assertThat(BindingScopeAnalysis.retain(bindings, Set.of())).isSameAs(EmptyBindingSet.getInstance());
		assertThat(BindingScopeAnalysis.retain(bindings, Set.of("y"))).isSameAs(EmptyBindingSet.getInstance());
		assertThat(BindingScopeAnalysis.retain(EmptyBindingSet.getInstance(), Set.of("y")))
				.isSameAs(EmptyBindingSet.getInstance());
	}

	private static StatementPattern pattern(String subject, String object) {
		return new StatementPattern(new Var(subject), new Var("_const_p", VF.createIRI("urn:p")), new Var(object));
	}
}
